float intersectRayPlane(vec3 org, vec3 dir, vec3 pos, vec3 n) {
    float d = dot(dir, n);
    return dot(pos - org, n) / d;
}

vec4 sampleWaveTexture(float iPlane, vec2 uv) {
    if ( max(abs(uv.x), abs(uv.y)) >= 1.0 ) return vec4(0.0);
    float h = .9 - wave(iPlane + iTime*.25, uv.x*.45+.5) * .6;
    float d = h - uv.y;
    float lineSize = 10.0/iResolution.y;
    if ( abs(d) < lineSize ) {
        float a = 1.0 - abs(d/lineSize);
        if ( d < 0.0 ) return vec4(a, a, a, 1.0);
        return vec4(a);
    }
    if ( d < 0.0 ) return vec4(0.0, 0.0, 0.0, 1.0);
    return vec4(0.0);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord/iResolution.xy - .5)*2.0;
    uv.y *= iResolution.y / iResolution.x;

    // Time varying pixel color
    vec3 col = vec3(0.0);
    vec3 left = vec3(1.0, 0.0, 0.0); 
    vec3 dir = vec3(0.0, 1.0, 1.0);
    dir = normalize(dir);
    vec3 pos = vec3(0.0, -100.5, -100.0); 
    vec3 up = cross(left, dir);
    vec3 org = pos + (left * uv.x + up * uv.y)*2.0;    

    int nPlanes = 60;
    float planeD = .04;

    vec4 cAcc = vec4(0.0);
    for ( int i=0; i<nPlanes; i++ ) {
        vec3 planePos = vec3(0.0, 0.0, float(i) * planeD); 
        vec3 planeNormal = vec3(0.0, 0.0, 1.0);
        float t = intersectRayPlane(org, dir, planePos, planeNormal);
        vec3 hit = org + dir * t;
        vec2 uv = hit.xy;
        vec4 c = sampleWaveTexture(float(i), uv);
        cAcc += c * (1.0 - cAcc.w);
        if ( cAcc.w >= 1.0 ) break; 
    }
    vec4 backc = vec4(0.3,0.3,0.3,1.0);
    cAcc += backc * (1.0 - cAcc.w);

    col = cAcc.xyz;
    // Output to screen
    fragColor = vec4(col,1.0);
}

uint pcgHash(uint i) {
    uint state = i * 747796405u + 2891336453u;
    uint word = ((state >> ((state >> 28) + 4u)) ^ state) * 277803737u;
    return ((word >> 22) ^ word) | 0xff000000u;
}

uvec3 pcgHash3d(uvec3 i) {
    uvec3 v = i * 1664525u + 1013904223u;
    v.x += v.y*v.z; v.y += v.z*v.x; v.z += v.x*v.y;
    uvec3 vs = uvec3(v.x >> 16, v.y >> 16, v.z >> 16);
    v ^= vs;
    v.x += v.y*v.z; v.y += v.z*v.x; v.z += v.x*v.y;
    return v;
}

float pcgHashf (float pos) { // [0..1]
    uint seed = floatBitsToUint(pos);
    uint p = pcgHash(seed);
    return float(p&0xffffu) * (1.0/65535.0);
}

vec3 pcgHashf3d (vec3 pos) { // [0..1]
    uvec3 seed = floatBitsToUint(pos);
    uvec3 p = pcgHash3d(seed);
    return vec3(p&0xffffu) * (1.0/65535.0);
}

float pcgHashLinear (float pos) { // [0..1]
    float i = floor(pos);
    float x0 = pcgHashf(i);
    float x1 = pcgHashf(i+1.0);
    return mix(x0, x1, pos-i);
}

vec3 pcgHashLinear2d (vec2 pos) { // [0..1]
    vec3 i = vec3(floor(pos), 0.0);
    vec3 x00 = pcgHashf3d(i);
    vec3 x10 = pcgHashf3d(i+vec3(1.0,0.0,0.0));
    vec3 x01 = pcgHashf3d(i+vec3(0.0,1.0,0.0));
    vec3 x11 = pcgHashf3d(i+vec3(1.0,1.0,0.0));
    vec3 x0 = mix(x00, x10, pos.x-i.x);
    vec3 x1 = mix(x01, x11, pos.x-i.x);
    return mix(x0, x1, pos.y-i.y);
}

float perlin (float pos, int octs) { // [0..1]
    float r = 0.5;
    float s = 1.0;
    for ( int i = 0; i<octs; i++ ) {
        r += (pcgHashLinear(pos) - .5)*s;
        pos += pos;
        s *= .5;
    }
    return clamp(r,0.0,1.0);
}

vec3 perlin2d (vec2 pos, int octs) { // [0..1]
    vec3 r = vec3(0.5);
    float s = .7;
    for ( int i = 0; i<octs; i++ ) {
        r += (pcgHashLinear2d(pos) - vec3(.5))*s;
        pos += pos;
        s *= .5;
    }
    return clamp(r,0.0,1.0);
}

float env(float iPlane, float t) { // 0..1
    t = fract(t);
    float delay = .15;
    float attack = .15;
    float sustain = .2;
    float release = .4;
    if ( t<delay ) return 0.0;
    if ( t<attack+delay ) return smoothstep(0.0,1.0,(t-delay)/attack);
    if ( t<attack+delay+sustain ) return 1.0;
    if ( t<attack+delay+sustain+release ) return 1.0 - smoothstep(0.0, 1.0, (t-(attack+delay+sustain))/release);
    return 0.0;
}

float wave(float iPlane, float t) { // 0..1
    float e = env(iPlane, t);
    float n = perlin2d(vec2(t*4.0, iPlane), 12).x;
    return e * n*n;
}

float sumWave(float t) {
    int nFreqs = 16;
    float sum = 0.0; 
    for ( int i=1; i<=nFreqs; i++ ) {
        // sine carrier frequency
        float f = 110.0 * float(i);
        float c = sin(6.2831*f*t);
        float w = wave(float(i), t);
        sum += c*w;
    }
    return sum / float(nFreqs);
}

vec2 mainSound( int samp, float time ) {
    float l = sumWave(time+0.25);
    float m = sumWave(time) * 2.0;
    float r = sumWave(time-0.2);

    return vec2(m-l, m+r) * .5;
}
